INSERT INTO `exemptions` (`id`, `description`, `created_at`, `updated_at`) VALUES
(1, 'Road Vehicle Standards (Model Reports— Compliance with Standards) Determination 2021 \r\n\r\nDivision 3—Prescription of standards: concessional and additional standards \r\n\r\nClause 21 Standards—rare vehicles \r\n\r\nSection (3) \r\n\r\nThe standards in subsection (2) apply to the exclusion of the following: \r\n\r\n(a) an applicable ADR, to the extent it requires the vehicle to be right-hand drive; \r\n\r\n(b) the following applicable ADRs, to the extent they require destructive testing to demonstrate compliance: \r\n\r\n \r\n\r\n(i) ADR 10—Steering Column; \r\n\r\n(ii) ADR 29—Side Door Strength; \r\n\r\n(iii) ADR 69—Full Frontal Impact Occupant Protection; \r\n\r\n(iv) ADR 72—Dynamic Side Impact Occupant Protection; \r\n\r\n(v) ADR 73—Offset Frontal Impact Occupant Protection; \r\n\r\n(vi) ADR 85—Pole Side Impact Performance; \r\n\r\n \r\n\r\nBased on the Model Reports— Compliance with Standards Determination, Clause 21 Standards—rare vehicles, exclusion of ADR 29—Side Door Strength is permitted. \r\n\r\nADR 29— Side Door Strength - Exempt / Not Applicable. ', '2024-06-27 08:03:06', NULL),
(2, 'ADR 30/01 Not Applicable. \r\n\r\nVehicle exempt as engine is not a diesel. ', '2024-06-27 08:04:18', NULL),
(3, 'ADR 44/02 Not Applicable.  This ADR is related for this type of vehicle. ', '2024-06-27 08:05:06', NULL),
(4, 'ADR 45/01 Not Applicable.  These types of lamps are not fitted to this vehicle. ', '2024-06-27 08:06:53', NULL);
