INSERT INTO `operation_hazards` (`id`, `vehicle_build_operation_id`, `hazard`, `control`, `created_at`, `updated_at`) VALUES
(1, 1, 'Manual handling of shell/panels', 'Two-plus person lift or hoist for shell; use body cart/rotisserie once landed.', '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(2, 1, 'Shell on stands — stability', 'Confirm stands/fixture rated for shell weight before releasing hoist.', '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(3, 2, 'Cutting / grinding sparks', 'Clear flammables from bay; fire extinguisher within reach.', '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(4, 2, 'Welding fumes / arc flash', 'Ventilated bay; welding mask and gauntlets.', '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(5, 3, 'Cutting / grinding sparks', 'Clear flammables from bay; fire extinguisher within reach.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(6, 3, 'Welding fumes / arc flash', 'Ventilated bay; welding mask and gauntlets.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(7, 4, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(8, 4, 'Cutting / grinding sparks', 'Clear flammables from bay; fire extinguisher within reach; eye and hand protection mandatory.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(9, 4, 'Welding fumes / arc flash', 'Local extraction or open bay ventilation; welding mask and gauntlets; screen off adjacent stations.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(10, 4, 'Suspended engine/component during removal', 'Use rated hoist/engine crane; no body parts under suspended load.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(11, 5, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(12, 5, 'Welding fumes / arc flash (tack weld)', 'Welding mask and gauntlets; ventilated bay.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(13, 5, 'Sharp cut edges on frame rail', 'Deburr edges or wear cut-resistant gloves when handling.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(14, 6, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(15, 6, 'K-member weight during fit-up', 'Support with engine crane or transmission jack while positioning; do not hand-hold under load.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(16, 6, 'Full-seam welding — fumes, arc flash, burns', 'Ventilation, welding mask/gauntlets, screen adjacent stations, allow cool-down before handling.', '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(17, 7, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(18, 7, 'Thread damage from cross-threading ball joint', 'Start by hand, use anti-seize, do not force.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(19, 8, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(20, 9, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(21, 9, 'Red thread locker — skin/eye contact', 'Wear gloves; avoid contact with skin and eyes.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(22, 10, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(23, 10, 'Spring under compression (coilover)', 'Handle assembled coilovers with care; do not disassemble spring/shock without a spring compressor.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(24, 11, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(25, 11, 'Tack/final weld of sway bar mounting brackets', 'Welding mask, ventilation, screen adjacent stations.', '2026-08-15 02:48:06', '2026-08-15 02:48:06'),
(26, 12, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(27, 13, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(28, 13, 'Road test of unproven suspension build', 'Low-speed shakedown first; check for noise, binding or looseness before normal driving.', '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(29, 14, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(30, 14, 'Suspended axle assembly', 'Support on rated stands/jack; no body parts under suspended load.', '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(31, 14, 'Welding fumes / arc flash', 'Ventilated bay; welding mask and gauntlets.', '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(32, 15, 'Spring under compression', 'Handle assembled coilovers with care; use a spring compressor if disassembling.', '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(33, 16, 'Brake fluid — skin/eye/paint contact', 'Wear gloves and glasses; wipe spills immediately, brake fluid damages paint.', '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(34, 17, 'Fuel vapour — fire risk', 'No open flame or grinding nearby; ensure bay ventilation.', '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(35, 17, 'Pressurised brake bleed', 'Wear eye protection; relieve pressure before disconnecting.', '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(36, 18, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(37, 18, 'Suspended engine/transmission load', 'Use rated hoist/crane; no body parts under suspended load.', '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(38, 19, 'Cutting/welding exhaust — sparks, fumes', 'Ventilated bay; fire extinguisher within reach.', '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(39, 20, 'Manual handling / sharp bracket edges', 'Deburr fabricated brackets; wear gloves when fitting.', '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(40, 21, 'Brake fluid — skin/eye/paint contact', 'Wear gloves and glasses; wipe spills immediately.', '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(41, 21, 'Refrigerant handling (A/C charging)', 'Only charge A/C with certified equipment and refrigerant handling licence.', '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(42, 22, 'Battery — short circuit / arc risk', 'Disconnect battery before harness work; insulate loose terminals.', '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(43, 23, 'Battery — short circuit / arc risk', 'Disconnect battery before harness work.', '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(44, 24, 'Paint / solvent fumes', 'Spray only in a ventilated, filtered booth.', '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(45, 24, 'Isocyanate exposure (2K paint)', 'Fresh-air-fed respirator required for 2K clear coat.', '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(46, 25, 'Manual handling of glass', 'Two-person lift for all glass panels.', '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(47, 26, 'First start — fire risk, hot surfaces', 'Fire extinguisher on hand for first start; clear bay of flammables.', '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(48, 27, 'Road test of new build', 'Low-speed shakedown first; check for noise, binding or looseness before normal driving.', '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(243, 137, 'Manual handling of shell/panels', 'Two-plus person lift or hoist for shell; use body cart/rotisserie once landed.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(244, 137, 'Shell on stands — stability', 'Confirm stands/fixture rated for shell weight before releasing hoist.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(245, 138, 'Cutting / grinding sparks', 'Clear flammables from bay; fire extinguisher within reach.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
