(247, 139, 'Cutting / grinding sparks', 'Clear flammables from bay; fire extinguisher within reach.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(248, 139, 'Welding fumes / arc flash', 'Ventilated bay; welding mask and gauntlets.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(249, 140, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(250, 140, 'Cutting / grinding sparks', 'Clear flammables from bay; fire extinguisher within reach; eye and hand protection mandatory.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(251, 140, 'Welding fumes / arc flash', 'Local extraction or open bay ventilation; welding mask and gauntlets; screen off adjacent stations.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(252, 140, 'Suspended engine/component during removal', 'Use rated hoist/engine crane; no body parts under suspended load.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(253, 141, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(254, 141, 'Welding fumes / arc flash (tack weld)', 'Welding mask and gauntlets; ventilated bay.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(255, 141, 'Sharp cut edges on frame rail', 'Deburr edges or wear cut-resistant gloves when handling.', '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(256, 142, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(257, 142, 'K-member weight during fit-up', 'Support with engine crane or transmission jack while positioning; do not hand-hold under load.', '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(258, 142, 'Full-seam welding — fumes, arc flash, burns', 'Ventilation, welding mask/gauntlets, screen adjacent stations, allow cool-down before handling.', '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(259, 143, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(260, 143, 'Thread damage from cross-threading ball joint', 'Start by hand, use anti-seize, do not force.', '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(261, 144, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(262, 145, 'Vehicle on jack stands / hoist', 'Stands on flat frame-rail sections near front body mounts only; confirm vehicle stability before working underneath.', '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
