(138, 54, 'OP-201', 'Rear Parcel Shelf Brace — Fabrication & Weld-In (ADR Seatbelt Mounting).', 'OP-202 — ADR-Compliant Seatbelt Mounting Plate Upgrade.', 'Chassis Fab Bay', 0, '<svg viewBox=\"0 0 640 340\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"JetBrains Mono, monospace\">\n  <!-- body side profile: fastback rear quarter, roofline to trunk -->\n  <g fill=\"none\" stroke=\"var(--text)\" stroke-width=\"2.2\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n    <!-- roofline sloping to decklid -->\n    <path d=\"M 40 70 L 150 40 L 300 40 L 470 130 L 560 150\"/>\n    <!-- rear glass -->\n    <path d=\"M 300 40 L 460 128\" stroke-dasharray=\"4 4\"/>\n    <!-- decklid / trunk lid -->\n    <path d=\"M 470 130 L 560 150 L 560 170 L 470 175 Z\"/>\n    <!-- rear body / quarter panel down to floor -->\n    <path d=\"M 40 70 L 40 260 L 600 260 L 600 175 L 560 170\"/>\n    <!-- rear bumper hint -->\n    <path d=\"M 560 230 L 620 230 L 620 250 L 560 250\"/>\n    <!-- rear seat back -->\n    <path d=\"M 60 200 L 60 260 M 60 200 Q 95 180 150 200 L 150 260\"/>\n    <!-- package tray / parcel shelf plane (shaded) -->\n    <path d=\"M 150 195 L 470 175 L 470 205 L 150 225 Z\" fill=\"var(--amber-dim)\" opacity=\"0.55\" stroke=\"var(--amber)\"/>\n    <!-- trunk floor -->\n    <path d=\"M 150 225 L 470 205 L 470 260 L 150 260 Z\" opacity=\"0.15\" fill=\"var(--text)\"/>\n    <!-- seatbelt anchor marks on parcel shelf -->\n    <circle cx=\"210\" cy=\"212\" r=\"4\" fill=\"var(--amber)\" stroke=\"none\"/>\n    <circle cx=\"300\" cy=\"205\" r=\"4\" fill=\"var(--amber)\" stroke=\"none\"/>\n    <circle cx=\"390\" cy=\"197\" r=\"4\" fill=\"var(--amber)\" stroke=\"none\"/>\n  </g>\n  <!-- callouts -->\n  <g font-size=\"12\" fill=\"var(--text)\">\n    <line x1=\"300\" y1=\"185\" x2=\"300\" y2=\"120\" stroke=\"var(--text)\" stroke-width=\"1\"/>\n    <text x=\"215\" y=\"112\">PARCEL SHELF BRACE</text>\n    <text x=\"240\" y=\"128\">welded across package tray</text>\n\n    <line x1=\"300\" y1=\"205\" x2=\"300\" y2=\"300\" stroke=\"var(--text)\" stroke-width=\"1\"/>\n    <text x=\"205\" y=\"315\">ADR SEATBELT ANCHOR POINTS (3x, rear)</text>\n\n    <line x1=\"105\" y1=\"220\" x2=\"60\" y2=\"90\" stroke=\"var(--text)\" stroke-width=\"1\"/>\n    <text x=\"20\" y=\"80\">REAR SEAT BACK</text>\n\n    <line x1=\"515\" y1=\"190\" x2=\"555\" y2=\"70\" stroke=\"var(--text)\" stroke-width=\"1\"/>\n    <text x=\"430\" y=\"60\">DECKLID / TRUNK OPENING</text>\n\n    <text x=\"40\" y=\"290\" font-size=\"11\" opacity=\"0.6\">Reflex angle fits to body — confirmed at fixture, OP-201 Step 2</text>\n  </g>\n</svg>\n', 'Original schematic — parcel shelf brace location & rear seatbelt anchor points (not to scale; reflex angle fits to body per Step 2)', NULL, '2026-08-15 04:00:41', '2026-08-15 07:16:30'),
