INSERT INTO `vehicle_build_steps` (`id`, `vehicle_build_operation_id`, `label`, `type`, `keypoint_text`, `image_path`, `image_caption`, `order`, `created_at`, `updated_at`) VALUES
(1, 1, 'Uncrate and inspect the new Dynacorn reproduction shell for shipping damage, panel alignment and e-coat/paint condition.', NULL, 'No teardown required — shell arrives as new sheet metal, not a restored body.', NULL, '', 1, '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(2, 1, 'Mount shell on rotisserie or chassis fixture; confirm level and square before any structural work begins.', NULL, '', NULL, '', 2, '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(3, 1, 'Dimensionally check core body points — shock tower centres, front rail width, rear frame rail length — against the Dynacorn spec sheet.', NULL, '⚠ Confirm dimensions before OP-201 — the parcel shelf brace and Front IFS install both depend on an accurate shell.', NULL, '', 3, '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(4, 1, 'Photograph shell condition and record any shipping damage claims before proceeding.', NULL, '', NULL, '', 4, '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(5, 2, 'Receive and inspect the parcel shelf assembly (P/N: [enter part number]) against the reference drawing — confirm mounting hole layout, ADR harness cut-outs and panel condition before fitting.', NULL, '✔ This is a supplied part, not fabricated on-site — check it against the drawing for shipping damage or defect, don\'t re-cut it.', 'parcel_shelf_drawing.jpg', 'Parcel shelf drawing — supplied part reference, P/N: [enter part number]', 1, '2026-08-15 02:48:04', '2026-08-15 07:16:30'),
(6, 2, 'Dry-fit the parcel shelf panel across the rear package tray, confirming it seats against the body\'s reflex angle and rear seat bulkhead.', NULL, '⚠ Reflex angle is body-specific — confirm the fold/seat angle against the actual shell in this fixture; no fixed spec is issued for this yet, fit to the body.', NULL, '', 2, '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(7, 2, 'Clamp the panel in place and tack weld the parcel shelf brace to the body structure at the marked points.', NULL, '', NULL, '', 3, '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(8, 2, 'Confirm fitment and structural alignment before final weld — check for panel oil-canning or gaps against the body.', NULL, '✔ No gaps or high spots before proceeding to final weld.', NULL, '', 4, '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(9, 2, 'Fully weld the parcel shelf brace to the body seam per structural weld standard.', NULL, '✔ Continuous weld bead, no gaps, cold-lap or pinholes.', NULL, '', 5, '2026-08-15 02:48:04', '2026-08-15 02:48:04'),
(10, 3, 'Locate factory seatbelt anchor points and confirm against the ADR seatbelt anchorage design rule.', NULL, '', NULL, '', 1, '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(11, 3, 'Remove or reinforce any factory mounting points that don\'t meet the compliant spec.', NULL, '', NULL, '', 2, '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(12, 3, 'Fit and weld ADR-compliant seatbelt mounting plates at the lower anchor, upper anchor (B-pillar) and inertia reel positions — tie rear mounts into the parcel shelf brace from OP-201.', NULL, '✔ Rear belt loads route through the parcel shelf brace, not bare sheet metal.', NULL, '', 3, '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(13, 3, 'Confirm all mounting plate welds and drill any clearance holes required for belt hardware.', NULL, '', NULL, '', 4, '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(14, 4, 'Raise vehicle and support on jack stands placed on the flat section of the frame rails, close to the front body mounts.', NULL, '⚠ Confirm stand placement before releasing hoist. Vehicle must not rock.', NULL, '', 1, '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(15, 4, 'Remove engine and transmission. Tag and bag all fasteners for re-installation.', NULL, '✔ Every fastener labelled by location — zero loose/unlabelled fasteners at end of step.', NULL, '', 2, '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(16, 4, 'Remove front wheels and shocks. Disconnect brake lines and tie rods.', NULL, 'Cap open brake lines to prevent fluid loss / contamination.', NULL, '', 3, '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(17, 4, 'Remove the factory steering box, pitman arm, and lower control arms. Unbolt the factory crossmember from the frame. Cut out the factory lower control arm mounts.', NULL, 'Reference cut lines only where marked — do not cut into the main frame rail.', 'p03_f0.jpg', 'Fig. 1 — cut-out control arm mounts', 4, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(18, 4, 'Cut out the factory shock towers, cutting along the edge between the shock tower and the inner apron for a clean line — passenger side.', NULL, '✔ Clean, straight cut on the apron edge — this becomes the weld joint for the new inner fender panel.', 'p04_f0.jpg', 'Fig. 2 — passenger side', 5, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(19, 4, 'Cut out the factory shock tower — driver\'s side.', NULL, '✔ Match passenger side cut line.', 'p04_f1.jpg', 'Fig. 3 — driver\'s side, tower removed', 6, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(20, 4, 'Grind and clean the remaining front frame rails — top, bottom, inner and outer faces — down to bare, weld-ready metal.', NULL, '✔ No paint, rust, or coating within the weld zone.', 'p04_f2.jpg', 'Fig. 4 — bottom view of engine bay', 7, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(21, 4, 'Measure 24-1/4\" from the very front of the frame and mark a vertical Sharpie line on each rail — passenger side shown.', NULL, '⚠ CRITICAL DIMENSION — re-check measurement on both sides before marking.', 'p05_f0.jpg', 'Fig. 5 — spindle centreline mark', 8, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(22, 4, 'Repeat the 24-1/4\" centreline mark — driver\'s side.', NULL, 'Error here affects final wheel alignment.', 'p05_f1.jpg', 'Fig. 6 — driver\'s side, 24 1/4\"', 9, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(23, 5, 'Place the driver\'s side shock tower saddle onto the frame rail. Orient so the upper control arm mount hole is higher at the front than the rear.', NULL, 'Confirm orientation before clamping — front hole higher than rear.', NULL, '', 1, '2026-08-15 02:48:05', '2026-08-15 02:48:05'),
(24, 5, 'Use the factory 7/16\" steering gear bolt to pre-locate the driver\'s side saddle, sliding it through the front ½\" hole in the saddle and the ½\" factory frame rail hole.', NULL, 'Factory bolt is an alignment guide only — discard once saddle is aligned.', 'p07_f0.jpg', 'Fig. 7A — driver\'s side alignment bolt', 2, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(25, 5, 'Use the factory 3/8\" idler arm bolt to pre-locate the passenger\'s side saddle through the rear ½\" hole in the saddle and the rear ½\" hole in the frame rail.', NULL, 'Discard factory bolt once aligned.', 'p07_f1.jpg', 'Fig. 7B — passenger side alignment bolt', 3, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(26, 5, 'Check the slot in each shock tower saddle against the spindle centreline mark made in OP-010. The vertical Sharpie line must be visible through the slot.', NULL, '⚠ Do not proceed until the centreline mark is visible through the slot on both sides.', 'p06_f0.jpg', 'Fig. 7 — saddle alignment window', 4, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(27, 5, 'Use adjustable clamps to securely snug both shock tower saddles to the frame rails, then tack weld in place.', NULL, '✔ Tack only — full weld occurs in OP-030 after K-member fit-up.', 'p06_f1.jpg', 'Fig. 8 — clamped for tack weld', 5, '2026-08-15 02:48:05', '2026-08-15 07:16:30'),
(28, 6, 'Place the front K-member into the vehicle, locating the vertical slots on the K-member to the vertical slots of the saddles. Use adjustable clamps to secure the K-member to the frame rail saddles and rear frame rails.', NULL, 'Slots must align — do not force; re-check saddle position if binding.', 'p08_f0.jpg', 'Fig. 9 — align slots at spindle centreline', 1, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(29, 6, 'Confirm the motor stands (pre-welded to the K-member) are correctly oriented before welding.', NULL, '✔ Re-check spindle centreline alignment before welding — last point to correct it.', 'p09_f0.jpg', 'Fig. 10 — motor stands, driver\'s side', 2, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(30, 6, 'Fully weld all seams and slots between the K-member and the vehicle frame — driver\'s side, view from outside vehicle.', NULL, '✔ Continuous weld bead, no gaps or cold-lap.', 'p10_f0.jpg', 'Fig. 11 — driver\'s side, outside view', 3, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(31, 6, 'Complete the weld — driver\'s side, view from engine compartment.', NULL, 'Grind smooth per your finishing standard.', 'p10_f1.jpg', 'Fig. 13 — driver\'s side, engine bay view', 4, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(32, 7, 'Apply anti-seize to the threads of the lower screw-in ball joint.', NULL, '✔ Anti-seize on every ball joint thread before install — no exceptions.', 'p11_f0.jpg', 'Fig. 14 — ball joint, anti-seize', 1, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(33, 7, 'Install the lower ball joint into the control arm housing. Tighten until tight to the housing.', NULL, 'Confirm ball joint seats fully — no gap to housing.', 'p11_f1.jpg', 'Fig. 15 — ball joint housing', 2, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(34, 7, 'Place the ball joint boot on the top side of the housing.', NULL, 'Boot orientation matters — top side only, or it will not seal correctly.', 'p11_f2.jpg', 'Fig. 16 — boot installed', 3, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(35, 7, 'Install the lower control arms. Use 5/8-11 x 4½\" hex bolts, washers and Nylock nuts for the front mount; 5/8-11 x 5\" hex bolts, washers and Nylock nuts for the rear mount. The cut-out on the bottom of the cross member is for the front bolt.', NULL, 'Torque per fastener spec sheet — do not fully torque until ride height is set, unless your procedure specifies otherwise.', 'p12_f0.jpg', 'Fig. 17/18 — control arm + cross-member cut-out', 4, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(36, 7, 'Confirm final control arm position and fastening.', NULL, 'Verify against fastener spec.', 'p12_f1.jpg', 'Fig. 19 — control arm installed', 5, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(37, 8, 'Install the upper control arm ball joints.', NULL, '', 'p13_f0.jpg', 'Fig. 20A — upper ball joint installed', 1, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(38, 8, 'Install the aluminium upper control arm slugs into the upper control arm slotted shaft for desired caster. Base kit ships with 0\" offset slugs (measured from bolt centre), giving 4–5° of caster.', NULL, 'If more caster is required, source offset slugs (1/16\" increments, Lefthander Chassis) rather than modifying the base slugs.', 'p13_f1.jpg', 'Fig. 21A — LHC upper control arm slugs', 2, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(39, 8, 'Reference: available slug offset options if a non-zero setting is needed.', NULL, 'Record offset used per side for the alignment log.', 'p14_f0.jpg', 'Fig. 21B — slug offset options', 3, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(40, 8, 'If adjusting camber beyond the base setting, add camber shim plates between the shock tower and the outside of the upper control arm shaft (Moog K960 kit).', NULL, 'Record shim thickness used per side for the alignment record in OP-100.', 'p14_f1.jpg', 'Fig. 21C — Moog K960 camber shims', 4, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(41, 8, 'Secure the upper control arm with the supplied ½-20 x 2¾\" Grade 8 hex bolts.', NULL, 'Torque per fastener spec sheet.', 'p15_f0.jpg', 'Fig. 21D — upper control arm assembled', 5, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(42, 9, 'Apply red thread locker to all steering arm fastener threads before installation.', NULL, '✔ Thread locker on every steering arm fastener — steering-critical joint.', 'p15_f1.jpg', 'Fig. 22 — thread locker on bolt', 1, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(43, 9, 'Install the steering arms to the spindles.', NULL, 'Confirm steering arms face forward before final torque.', 'p15_f2.jpg', 'Fig. 23 — steering arm', 2, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(44, 9, 'Install the spindle over the lower ball joint first. Thread the castle nut over the washer to secure the spindle to the lower ball joint.', NULL, '', 'p16_f0.jpg', 'Fig. 24 — steering arms face forward', 3, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(45, 9, 'Attach the upper ball joint to the spindle.', NULL, 'Confirm orientation matches Fig. 24 reference.', 'p16_f1.jpg', 'Fig. 25 — spindle attached to ball joints', 4, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(46, 9, 'Torque castle nuts to spec and fit new cotter pins through both upper and lower ball joints.', NULL, '⚠ Steering-critical fastener — do not reuse cotter pins. Advance torque (never back off) to align the slot.', 'p17_f0.jpg', 'Fig. 26 — castle nut installed', 5, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(47, 10, 'Install the coil-over shocks. Use ½-20 x 2¾\" Grade 8 hex bolts, washers and Nylock nuts for the lower control arm mount.', NULL, '', 'p17_f1.jpg', 'Fig. 27 — coilover installed', 1, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(48, 10, 'Confirm the adjuster knob faces in-board for ease of adjustment.', NULL, '⚠ Adjuster orientation — in-board on both sides, or later adjustment access is blocked by the frame.', 'p17_f2.jpg', 'Fig. 28 — adjuster knob orientation', 2, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(49, 10, 'Use ½-20 x 5\" Grade 8 hex bolts, washers and Nylock nuts along with the aluminium shock spacers (MTF-216) to secure the shock to the upper mount.', NULL, 'Torque per fastener spec sheet.', 'p18_f0.jpg', 'Fig. 29 — upper shock mount', 3, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(50, 10, 'Confirm final coilover position and fastening.', NULL, 'Verify spacer count — 4 total across both sides.', 'p18_f1.jpg', 'Fig. 30 — upper mount detail', 4, '2026-08-15 02:48:06', '2026-08-15 07:16:30'),
(51, 11, 'Attach the sway bar to the adjustable end links and mount the end links snug to the lower control arm mounts. Confirm end links sit straight up and down, front-to-rear and left-to-right. Apply anti-seize to adjustable link threads.', NULL, 'Mount the female rod end on the top side to avoid trapping water in the threads.', 'p18_f2.jpg', 'Fig. 31/32 — end link assembly', 1, '2026-08-15 02:48:07', '2026-08-15 07:16:30'),
(52, 11, 'Install the sway bar bushings using 7/16-14 x 1½\" Grade 8 bolts, washers and Nylock nuts, with 3/8\" spacers, to the sway bar mounting brackets. Clamp the assembly to the factory frame — driver\'s side shown.', NULL, 'Re-check end link bushings are still straight up and down before tacking.', 'p19_f0.jpg', 'Fig. 33 — driver\'s side, clamped', 2, '2026-08-15 02:48:07', '2026-08-15 07:16:30'),
(53, 11, 'Once the mounting bracket is flush with the bottom of the frame, tack weld the mounting bracket to the frame.', NULL, '', 'p19_f1.jpg', 'Fig. 34 — mounting bracket tacked', 3, '2026-08-15 02:48:07', '2026-08-15 07:16:30'),
(54, 11, 'Install and tighten the sway bar collars. Once the sway bar is at the desired location, fully weld the sway bar mounting brackets to the frame.', NULL, '✔ Full weld only after collar position confirmed correct — rework after full weld is difficult.', 'p19_f3.jpg', 'Fig. 35 — collar installed', 4, '2026-08-15 02:48:07', '2026-08-15 07:16:30'),
(55, 11, 'Grease the bushings and install the splined sway bar and torsion arm, confirming the adjustable link is straight up and down, front-to-rear and right-to-left — full underside view.', NULL, '', 'p20_f0.jpg', 'Fig. 36 — full assembly, underside', 5, '2026-08-15 02:48:07', '2026-08-15 07:16:30'),
(56, 11, 'Confirm bushing and clamping collar seating from inside the sway bar mount.', NULL, 'Passenger side shown — mirror for driver\'s side.', 'p20_f1.jpg', 'Fig. 37 — bushing & collar detail', 6, '2026-08-15 02:48:07', '2026-08-15 07:16:30'),
(57, 11, 'Confirm splined sway bar final position, passenger side.', NULL, '', 'p21_f0.jpg', 'Fig. 38 — splined sway bar, passenger side', 7, '2026-08-15 02:48:07', '2026-08-15 07:16:30'),
(58, 12, 'Install the billet rack mount brackets on top of the rack mount tabs. Remove the billet rack mount caps and position the rack and pinion in place.', NULL, '', NULL, '', 1, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(59, 12, 'Use the four socket head cap screw bolts to fasten the rack & pinion and rack mounts to the cross member. Attach the outer tie rod to the steering arm.', NULL, 'Torque per fastener spec sheet. Confirm tie rod boot is not twisted or pinched before final torque.', 'p21_f1.jpg', 'Fig. 39/40 — rack & pinion installed', 2, '2026-08-15 02:48:07', '2026-08-15 07:16:30'),
(60, 13, 'Set the vehicle at final ride height with the lower control arms level before setting alignment.', NULL, '⚠ Alignment must be set at ride height, not on the hoist with suspension drooped.', NULL, '', 1, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(61, 13, 'Set caster using the upper control arm mount slugs installed in OP-050. Zero-offset slugs should fall within the recommended caster window.', NULL, 'Target: 3° to 6° positive caster.', NULL, '', 2, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(62, 13, 'Set camber by adding or subtracting camber shim plates at the upper control arm.', NULL, 'Target: 0° to 2° negative camber.', NULL, '', 3, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(63, 13, 'Set toe.', NULL, 'Target: 0 to 1/16\" toe-in.', NULL, '', 4, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(64, 13, 'Confirm both sides have equal caster settings.', NULL, '⚠ Unequal caster side-to-side will cause the vehicle to pull — do not release for road test until matched.', NULL, '', 5, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(65, 13, 'Road test for a few hundred miles, then re-check ride height and alignment. Springs may settle and change ride height/camber — re-adjust ride height before re-checking alignment.', NULL, 'Schedule a follow-up alignment check post-settling before final customer/compliance sign-off.', NULL, '', 6, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(66, 14, 'Position rear axle assembly under the vehicle at correct ride height and pinion angle.', NULL, '', NULL, '', 1, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(67, 14, 'Fit 4-link/torque arm brackets and Panhard/Watts link mount, confirming axle centreline against chassis centreline.', NULL, '⚠ CRITICAL — axle centreline must match chassis centreline before any welding.', NULL, '', 2, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(68, 14, 'Tack weld all mounting brackets; verify axle is square before final weld.', NULL, '', NULL, '', 3, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(69, 14, 'Fully weld all mounting brackets to the frame.', NULL, '✔ Continuous weld bead, no gaps.', NULL, '', 4, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(70, 15, 'Install rear coilovers/springs and shocks per kit instructions; confirm ride height.', NULL, '', NULL, '', 1, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(71, 15, 'Route parking brake cables clear of exhaust, driveshaft and moving suspension components.', NULL, '✔ Check clearance through full suspension travel, not just static.', NULL, '', 2, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(72, 15, 'Torque all suspension fasteners to spec.', NULL, '', NULL, '', 3, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(73, 16, 'Install master cylinder, booster (if fitted) and proportioning valve.', NULL, '', NULL, '', 1, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(74, 16, 'Fabricate and route brake lines front to rear, securing with mounting clips at factory intervals.', NULL, 'No line within 50mm of exhaust or moving suspension without a heat shield/clearance check.', NULL, '', 2, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(75, 16, 'Connect lines to calipers/wheel cylinders; torque all fittings to spec.', NULL, '', NULL, '', 3, '2026-08-15 02:48:07', '2026-08-15 02:48:07'),
(76, 17, 'Install fuel cell/tank and mounting straps; connect fuel supply/return lines and vent per fuel system diagram.', NULL, '', NULL, '', 1, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(77, 17, 'Pressure/leak-test fuel system before first start.', NULL, '⚠ Do not proceed to OP-601 first start until fuel system passes leak test.', NULL, '', 2, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(78, 17, 'Bench or manual bleed the complete brake system; verify pedal feel and no leaks.', NULL, '', NULL, '', 3, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(79, 18, 'Lower engine/transmission assembly onto mounts; confirm mount alignment and clearance to chassis/body.', NULL, '', NULL, '', 1, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(80, 18, 'Connect engine mounts, transmission crossmember and driveline accessories.', NULL, '', NULL, '', 2, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(81, 18, 'Torque all mounting hardware to spec.', NULL, '✔ Re-check torque after first heat cycle.', NULL, '', 3, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(82, 19, 'Fit driveshaft; confirm u-joint angles and slip-yoke engagement.', NULL, '', NULL, '', 1, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(83, 19, 'Fabricate and install exhaust system, maintaining clearance from fuel lines, brake lines and floor.', NULL, 'Minimum clearance per your fabrication standard — check at full suspension travel.', NULL, '', 2, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(84, 20, 'Install radiator and confirm clearance to fan, core support and A/C condenser.', NULL, '', NULL, '', 1, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(85, 20, 'Install brake booster / master cylinder assembly at the firewall.', NULL, '', NULL, '', 2, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(86, 20, 'Fabricate and fit the mounting bracket for the electric master cylinder pump under the front fender, passenger side.', NULL, '✔ Confirm bracket location matches this build\'s standard — passenger side, under-fender.', NULL, '', 3, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(87, 20, 'Fabricate and fit the mounting bracket for the electric A/C pump under the front fender, driver side.', NULL, '✔ Confirm bracket location matches this build\'s standard — driver side, under-fender.', NULL, '', 4, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(88, 20, 'Confirm clearance to wheel, tyre and suspension travel for both fender-mounted pump brackets through full lock and full suspension travel.', NULL, '⚠ Check at full steering lock and full bump/droop — not just static.', NULL, '', 5, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(89, 21, 'Run brake lines from the electric master cylinder pump (passenger fender) to the booster/master cylinder and forward to the front brake circuit fabricated in OP-501.', NULL, '', NULL, '', 1, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(90, 21, 'Run A/C lines from the electric A/C pump (driver fender) to the compressor/condenser circuit.', NULL, '', NULL, '', 2, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(91, 21, 'Route coolant hoses between radiator and engine, clear of exhaust and moving components.', NULL, '', NULL, '', 3, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(92, 21, 'Secure all lines with mounting clips at factory-style intervals; confirm no chafe points through full steering and suspension travel.', NULL, '⚠ Check at full steering lock and full suspension travel, both fender pump lines included.', NULL, '', 4, '2026-08-15 02:48:08', '2026-08-15 02:48:08'),
(93, 22, 'Route and secure chassis wiring harness, keeping clear of heat sources and moving parts.', NULL, '', NULL, '', 1, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(94, 22, 'Connect lighting, fuel sender and chassis grounds; verify continuity at each circuit.', NULL, '', NULL, '', 2, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(95, 22, 'Confirm no shorts to chassis before battery connection.', NULL, '⚠ Do not connect battery until this check passes.', NULL, '', 3, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(96, 23, 'Connect engine harness to ECU and sensors; verify pinout against wiring diagram.', NULL, '', NULL, '', 1, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(97, 23, 'Wire gauge cluster, switch panel and accessory circuits; label all fuses/relays.', NULL, '✔ Every fuse/relay labelled and matched to the wiring diagram.', NULL, '', 2, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(98, 23, 'Power up and confirm ECU communication, gauge function and no fault codes.', NULL, '', NULL, '', 3, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(99, 24, 'Fit and align all body panels; confirm gaps and shut lines within spec.', NULL, '', NULL, '', 1, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(100, 24, 'Complete bodywork, filler and surface prep; seal and prime.', NULL, '', NULL, '', 2, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(101, 24, 'Apply base coat and clear coat in a controlled, ventilated booth; cure per paint manufacturer spec.', NULL, '⚠ Full respiratory protection required for 2K clear coat application.', NULL, '', 3, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(102, 24, 'Colour-sand and buff finished paint.', NULL, '', NULL, '', 4, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(103, 25, 'Install sound deadening, carpet, seats, seatbelts and console.', NULL, '', NULL, '', 1, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(104, 25, 'Install dash, gauges and interior trim.', NULL, '', NULL, '', 2, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(105, 25, 'Install glass, exterior trim and weatherstrip; confirm seals against water/wind intrusion.', NULL, '', NULL, '', 3, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(106, 26, 'Fill all fluids — oil, coolant, transmission, differential, brake, power steering — to spec.', NULL, '', NULL, '', 1, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(107, 26, 'Perform initial start-up with fire extinguisher on hand; check for leaks, unusual noise and correct idle.', NULL, '⚠ First start — extinguisher on hand, bay clear of flammables.', NULL, '', 2, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(108, 26, 'Function-check all electrical systems: lighting, HVAC, wipers, gauges, infotainment.', NULL, '', NULL, '', 3, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(109, 27, 'Set final wheel alignment (caster, camber, toe) per Front IFS spec (OP-100) and rear suspension spec.', NULL, '', NULL, '', 1, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(110, 27, 'Complete low-speed shakedown, then extended road test; re-check alignment and torque all suspension/steering fasteners after settling.', NULL, '', NULL, '', 2, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(111, 27, 'Complete ADR/RVSA compliance inspection checklist and compile compliance documentation for submission.', NULL, '', NULL, '', 3, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(112, 27, 'Final detail and pre-delivery inspection.', NULL, '', NULL, '', 4, '2026-08-15 02:48:09', '2026-08-15 02:48:09'),
(565, 137, 'Uncrate and inspect the new Dynacorn reproduction shell for shipping damage, panel alignment and e-coat/paint condition.', NULL, 'No teardown required — shell arrives as new sheet metal, not a restored body.', NULL, NULL, 0, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(566, 137, 'Mount shell on rotisserie or chassis fixture; confirm level and square before any structural work begins.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(567, 137, 'Dimensionally check core body points — shock tower centres, front rail width, rear frame rail length — against the Dynacorn spec sheet.', NULL, '⚠ Confirm dimensions before OP-201 — the parcel shelf brace and Front IFS install both depend on an accurate shell.', NULL, NULL, 2, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(568, 137, 'Photograph shell condition and record any shipping damage claims before proceeding.', NULL, NULL, NULL, NULL, 3, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(569, 138, 'Receive and inspect the parcel shelf assembly (P/N: [enter part number]) against the reference drawing — confirm mounting hole layout, ADR harness cut-outs and panel condition before fitting.', NULL, '✔ This is a supplied part, not fabricated on-site — check it against the drawing for shipping damage or defect, don\'t re-cut it.', 'parcel_shelf_drawing.jpg', 'Parcel shelf drawing — supplied part reference, P/N: [enter part number]', 0, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(570, 138, 'Dry-fit the parcel shelf panel across the rear package tray, confirming it seats against the body\'s reflex angle and rear seat bulkhead.', NULL, '⚠ Reflex angle is body-specific — confirm the fold/seat angle against the actual shell in this fixture; no fixed spec is issued for this yet, fit to the body.', NULL, NULL, 1, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(571, 138, 'Clamp the panel in place and tack weld the parcel shelf brace to the body structure at the marked points.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(572, 138, 'Confirm fitment and structural alignment before final weld — check for panel oil-canning or gaps against the body.', NULL, '✔ No gaps or high spots before proceeding to final weld.', NULL, NULL, 3, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(573, 138, 'Fully weld the parcel shelf brace to the body seam per structural weld standard.', NULL, '✔ Continuous weld bead, no gaps, cold-lap or pinholes.', NULL, NULL, 4, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(574, 139, 'Locate factory seatbelt anchor points and confirm against the ADR seatbelt anchorage design rule.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(575, 139, 'Remove or reinforce any factory mounting points that don\'t meet the compliant spec.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(576, 139, 'Fit and weld ADR-compliant seatbelt mounting plates at the lower anchor, upper anchor (B-pillar) and inertia reel positions — tie rear mounts into the parcel shelf brace from OP-201.', NULL, '✔ Rear belt loads route through the parcel shelf brace, not bare sheet metal.', NULL, NULL, 2, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(577, 139, 'Confirm all mounting plate welds and drill any clearance holes required for belt hardware.', NULL, NULL, NULL, NULL, 3, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(578, 140, 'Raise vehicle and support on jack stands placed on the flat section of the frame rails, close to the front body mounts.', NULL, '⚠ Confirm stand placement before releasing hoist. Vehicle must not rock.', NULL, NULL, 0, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(579, 140, 'Remove engine and transmission. Tag and bag all fasteners for re-installation.', NULL, '✔ Every fastener labelled by location — zero loose/unlabelled fasteners at end of step.', NULL, NULL, 1, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(580, 140, 'Remove front wheels and shocks. Disconnect brake lines and tie rods.', NULL, 'Cap open brake lines to prevent fluid loss / contamination.', NULL, NULL, 2, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(581, 140, 'Remove the factory steering box, pitman arm, and lower control arms. Unbolt the factory crossmember from the frame. Cut out the factory lower control arm mounts.', NULL, 'Reference cut lines only where marked — do not cut into the main frame rail.', 'p03_f0.jpg', 'Fig. 1 — cut-out control arm mounts', 3, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(582, 140, 'Cut out the factory shock towers, cutting along the edge between the shock tower and the inner apron for a clean line — passenger side.', NULL, '✔ Clean, straight cut on the apron edge — this becomes the weld joint for the new inner fender panel.', 'p04_f0.jpg', 'Fig. 2 — passenger side', 4, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(583, 140, 'Cut out the factory shock tower — driver\'s side.', NULL, '✔ Match passenger side cut line.', 'p04_f1.jpg', 'Fig. 3 — driver\'s side, tower removed', 5, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(584, 140, 'Grind and clean the remaining front frame rails — top, bottom, inner and outer faces — down to bare, weld-ready metal.', NULL, '✔ No paint, rust, or coating within the weld zone.', 'p04_f2.jpg', 'Fig. 4 — bottom view of engine bay', 6, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(585, 140, 'Measure 24-1/4\" from the very front of the frame and mark a vertical Sharpie line on each rail — passenger side shown.', NULL, '⚠ CRITICAL DIMENSION — re-check measurement on both sides before marking.', 'p05_f0.jpg', 'Fig. 5 — spindle centreline mark', 7, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(586, 140, 'Repeat the 24-1/4\" centreline mark — driver\'s side.', NULL, 'Error here affects final wheel alignment.', 'p05_f1.jpg', 'Fig. 6 — driver\'s side, 24 1/4\"', 8, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(587, 141, 'Place the driver\'s side shock tower saddle onto the frame rail. Orient so the upper control arm mount hole is higher at the front than the rear.', NULL, 'Confirm orientation before clamping — front hole higher than rear.', NULL, NULL, 0, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(588, 141, 'Use the factory 7/16\" steering gear bolt to pre-locate the driver\'s side saddle, sliding it through the front ½\" hole in the saddle and the ½\" factory frame rail hole.', NULL, 'Factory bolt is an alignment guide only — discard once saddle is aligned.', 'p07_f0.jpg', 'Fig. 7A — driver\'s side alignment bolt', 1, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(589, 141, 'Use the factory 3/8\" idler arm bolt to pre-locate the passenger\'s side saddle through the rear ½\" hole in the saddle and the rear ½\" hole in the frame rail.', NULL, 'Discard factory bolt once aligned.', 'p07_f1.jpg', 'Fig. 7B — passenger side alignment bolt', 2, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(590, 141, 'Check the slot in each shock tower saddle against the spindle centreline mark made in OP-010. The vertical Sharpie line must be visible through the slot.', NULL, '⚠ Do not proceed until the centreline mark is visible through the slot on both sides.', 'p06_f0.jpg', 'Fig. 7 — saddle alignment window', 3, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(591, 141, 'Use adjustable clamps to securely snug both shock tower saddles to the frame rails, then tack weld in place.', NULL, '✔ Tack only — full weld occurs in OP-030 after K-member fit-up.', 'p06_f1.jpg', 'Fig. 8 — clamped for tack weld', 4, '2026-08-15 04:00:41', '2026-08-15 04:00:41'),
(592, 142, 'Place the front K-member into the vehicle, locating the vertical slots on the K-member to the vertical slots of the saddles. Use adjustable clamps to secure the K-member to the frame rail saddles and rear frame rails.', NULL, 'Slots must align — do not force; re-check saddle position if binding.', 'p08_f0.jpg', 'Fig. 9 — align slots at spindle centreline', 0, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(593, 142, 'Confirm the motor stands (pre-welded to the K-member) are correctly oriented before welding.', NULL, '✔ Re-check spindle centreline alignment before welding — last point to correct it.', 'p09_f0.jpg', 'Fig. 10 — motor stands, driver\'s side', 1, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(594, 142, 'Fully weld all seams and slots between the K-member and the vehicle frame — driver\'s side, view from outside vehicle.', NULL, '✔ Continuous weld bead, no gaps or cold-lap.', 'p10_f0.jpg', 'Fig. 11 — driver\'s side, outside view', 2, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(595, 142, 'Complete the weld — driver\'s side, view from engine compartment.', NULL, 'Grind smooth per your finishing standard.', 'p10_f1.jpg', 'Fig. 13 — driver\'s side, engine bay view', 3, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(596, 143, 'Apply anti-seize to the threads of the lower screw-in ball joint.', NULL, '✔ Anti-seize on every ball joint thread before install — no exceptions.', 'p11_f0.jpg', 'Fig. 14 — ball joint, anti-seize', 0, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(597, 143, 'Install the lower ball joint into the control arm housing. Tighten until tight to the housing.', NULL, 'Confirm ball joint seats fully — no gap to housing.', 'p11_f1.jpg', 'Fig. 15 — ball joint housing', 1, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(598, 143, 'Place the ball joint boot on the top side of the housing.', NULL, 'Boot orientation matters — top side only, or it will not seal correctly.', 'p11_f2.jpg', 'Fig. 16 — boot installed', 2, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(599, 143, 'Install the lower control arms. Use 5/8-11 x 4½\" hex bolts, washers and Nylock nuts for the front mount; 5/8-11 x 5\" hex bolts, washers and Nylock nuts for the rear mount. The cut-out on the bottom of the cross member is for the front bolt.', NULL, 'Torque per fastener spec sheet — do not fully torque until ride height is set, unless your procedure specifies otherwise.', 'p12_f0.jpg', 'Fig. 17/18 — control arm + cross-member cut-out', 3, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(600, 143, 'Confirm final control arm position and fastening.', NULL, 'Verify against fastener spec.', 'p12_f1.jpg', 'Fig. 19 — control arm installed', 4, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(601, 144, 'Install the upper control arm ball joints.', NULL, NULL, 'p13_f0.jpg', 'Fig. 20A — upper ball joint installed', 0, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(602, 144, 'Install the aluminium upper control arm slugs into the upper control arm slotted shaft for desired caster. Base kit ships with 0\" offset slugs (measured from bolt centre), giving 4–5° of caster.', NULL, 'If more caster is required, source offset slugs (1/16\" increments, Lefthander Chassis) rather than modifying the base slugs.', 'p13_f1.jpg', 'Fig. 21A — LHC upper control arm slugs', 1, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(603, 144, 'Reference: available slug offset options if a non-zero setting is needed.', NULL, 'Record offset used per side for the alignment log.', 'p14_f0.jpg', 'Fig. 21B — slug offset options', 2, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(604, 144, 'If adjusting camber beyond the base setting, add camber shim plates between the shock tower and the outside of the upper control arm shaft (Moog K960 kit).', NULL, 'Record shim thickness used per side for the alignment record in OP-100.', 'p14_f1.jpg', 'Fig. 21C — Moog K960 camber shims', 3, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(605, 144, 'Secure the upper control arm with the supplied ½-20 x 2¾\" Grade 8 hex bolts.', NULL, 'Torque per fastener spec sheet.', 'p15_f0.jpg', 'Fig. 21D — upper control arm assembled', 4, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(606, 145, 'Apply red thread locker to all steering arm fastener threads before installation.', NULL, '✔ Thread locker on every steering arm fastener — steering-critical joint.', 'p15_f1.jpg', 'Fig. 22 — thread locker on bolt', 0, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(607, 145, 'Install the steering arms to the spindles.', NULL, 'Confirm steering arms face forward before final torque.', 'p15_f2.jpg', 'Fig. 23 — steering arm', 1, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(608, 145, 'Install the spindle over the lower ball joint first. Thread the castle nut over the washer to secure the spindle to the lower ball joint.', NULL, NULL, 'p16_f0.jpg', 'Fig. 24 — steering arms face forward', 2, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(609, 145, 'Attach the upper ball joint to the spindle.', NULL, 'Confirm orientation matches Fig. 24 reference.', 'p16_f1.jpg', 'Fig. 25 — spindle attached to ball joints', 3, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(610, 145, 'Torque castle nuts to spec and fit new cotter pins through both upper and lower ball joints.', NULL, '⚠ Steering-critical fastener — do not reuse cotter pins. Advance torque (never back off) to align the slot.', 'p17_f0.jpg', 'Fig. 26 — castle nut installed', 4, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(611, 146, 'Install the coil-over shocks. Use ½-20 x 2¾\" Grade 8 hex bolts, washers and Nylock nuts for the lower control arm mount.', NULL, NULL, 'p17_f1.jpg', 'Fig. 27 — coilover installed', 0, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(612, 146, 'Confirm the adjuster knob faces in-board for ease of adjustment.', NULL, '⚠ Adjuster orientation — in-board on both sides, or later adjustment access is blocked by the frame.', 'p17_f2.jpg', 'Fig. 28 — adjuster knob orientation', 1, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(613, 146, 'Use ½-20 x 5\" Grade 8 hex bolts, washers and Nylock nuts along with the aluminium shock spacers (MTF-216) to secure the shock to the upper mount.', NULL, 'Torque per fastener spec sheet.', 'p18_f0.jpg', 'Fig. 29 — upper shock mount', 2, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(614, 146, 'Confirm final coilover position and fastening.', NULL, 'Verify spacer count — 4 total across both sides.', 'p18_f1.jpg', 'Fig. 30 — upper mount detail', 3, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(615, 147, 'Attach the sway bar to the adjustable end links and mount the end links snug to the lower control arm mounts. Confirm end links sit straight up and down, front-to-rear and left-to-right. Apply anti-seize to adjustable link threads.', NULL, 'Mount the female rod end on the top side to avoid trapping water in the threads.', 'p18_f2.jpg', 'Fig. 31/32 — end link assembly', 0, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(616, 147, 'Install the sway bar bushings using 7/16-14 x 1½\" Grade 8 bolts, washers and Nylock nuts, with 3/8\" spacers, to the sway bar mounting brackets. Clamp the assembly to the factory frame — driver\'s side shown.', NULL, 'Re-check end link bushings are still straight up and down before tacking.', 'p19_f0.jpg', 'Fig. 33 — driver\'s side, clamped', 1, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(617, 147, 'Once the mounting bracket is flush with the bottom of the frame, tack weld the mounting bracket to the frame.', NULL, NULL, 'p19_f1.jpg', 'Fig. 34 — mounting bracket tacked', 2, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(618, 147, 'Install and tighten the sway bar collars. Once the sway bar is at the desired location, fully weld the sway bar mounting brackets to the frame.', NULL, '✔ Full weld only after collar position confirmed correct — rework after full weld is difficult.', 'p19_f3.jpg', 'Fig. 35 — collar installed', 3, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(619, 147, 'Grease the bushings and install the splined sway bar and torsion arm, confirming the adjustable link is straight up and down, front-to-rear and right-to-left — full underside view.', NULL, NULL, 'p20_f0.jpg', 'Fig. 36 — full assembly, underside', 4, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(620, 147, 'Confirm bushing and clamping collar seating from inside the sway bar mount.', NULL, 'Passenger side shown — mirror for driver\'s side.', 'p20_f1.jpg', 'Fig. 37 — bushing & collar detail', 5, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(621, 147, 'Confirm splined sway bar final position, passenger side.', NULL, NULL, 'p21_f0.jpg', 'Fig. 38 — splined sway bar, passenger side', 6, '2026-08-15 04:00:42', '2026-08-15 04:00:42'),
(622, 148, 'Install the billet rack mount brackets on top of the rack mount tabs. Remove the billet rack mount caps and position the rack and pinion in place.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(623, 148, 'Use the four socket head cap screw bolts to fasten the rack & pinion and rack mounts to the cross member. Attach the outer tie rod to the steering arm.', NULL, 'Torque per fastener spec sheet. Confirm tie rod boot is not twisted or pinched before final torque.', 'p21_f1.jpg', 'Fig. 39/40 — rack & pinion installed', 1, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(624, 149, 'Set the vehicle at final ride height with the lower control arms level before setting alignment.', NULL, '⚠ Alignment must be set at ride height, not on the hoist with suspension drooped.', NULL, NULL, 0, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(625, 149, 'Set caster using the upper control arm mount slugs installed in OP-050. Zero-offset slugs should fall within the recommended caster window.', NULL, 'Target: 3° to 6° positive caster.', NULL, NULL, 1, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(626, 149, 'Set camber by adding or subtracting camber shim plates at the upper control arm.', NULL, 'Target: 0° to 2° negative camber.', NULL, NULL, 2, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(627, 149, 'Set toe.', NULL, 'Target: 0 to 1/16\" toe-in.', NULL, NULL, 3, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(628, 149, 'Confirm both sides have equal caster settings.', NULL, '⚠ Unequal caster side-to-side will cause the vehicle to pull — do not release for road test until matched.', NULL, NULL, 4, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(629, 149, 'Road test for a few hundred miles, then re-check ride height and alignment. Springs may settle and change ride height/camber — re-adjust ride height before re-checking alignment.', NULL, 'Schedule a follow-up alignment check post-settling before final customer/compliance sign-off.', NULL, NULL, 5, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(630, 150, 'Position rear axle assembly under the vehicle at correct ride height and pinion angle.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(631, 150, 'Fit 4-link/torque arm brackets and Panhard/Watts link mount, confirming axle centreline against chassis centreline.', NULL, '⚠ CRITICAL — axle centreline must match chassis centreline before any welding.', NULL, NULL, 1, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(632, 150, 'Tack weld all mounting brackets; verify axle is square before final weld.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(633, 150, 'Fully weld all mounting brackets to the frame.', NULL, '✔ Continuous weld bead, no gaps.', NULL, NULL, 3, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(634, 151, 'Install rear coilovers/springs and shocks per kit instructions; confirm ride height.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(635, 151, 'Route parking brake cables clear of exhaust, driveshaft and moving suspension components.', NULL, '✔ Check clearance through full suspension travel, not just static.', NULL, NULL, 1, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(636, 151, 'Torque all suspension fasteners to spec.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(637, 152, 'Install master cylinder, booster (if fitted) and proportioning valve.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(638, 152, 'Fabricate and route brake lines front to rear, securing with mounting clips at factory intervals.', NULL, 'No line within 50mm of exhaust or moving suspension without a heat shield/clearance check.', NULL, NULL, 1, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(639, 152, 'Connect lines to calipers/wheel cylinders; torque all fittings to spec.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(640, 153, 'Install fuel cell/tank and mounting straps; connect fuel supply/return lines and vent per fuel system diagram.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(641, 153, 'Pressure/leak-test fuel system before first start.', NULL, '⚠ Do not proceed to OP-601 first start until fuel system passes leak test.', NULL, NULL, 1, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(642, 153, 'Bench or manual bleed the complete brake system; verify pedal feel and no leaks.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(643, 154, 'Lower engine/transmission assembly onto mounts; confirm mount alignment and clearance to chassis/body.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(644, 154, 'Connect engine mounts, transmission crossmember and driveline accessories.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(645, 154, 'Torque all mounting hardware to spec.', NULL, '✔ Re-check torque after first heat cycle.', NULL, NULL, 2, '2026-08-15 04:00:43', '2026-08-15 04:00:43'),
(646, 155, 'Fit driveshaft; confirm u-joint angles and slip-yoke engagement.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(647, 155, 'Fabricate and install exhaust system, maintaining clearance from fuel lines, brake lines and floor.', NULL, 'Minimum clearance per your fabrication standard — check at full suspension travel.', NULL, NULL, 1, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(648, 156, 'Install radiator and confirm clearance to fan, core support and A/C condenser.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(649, 156, 'Install brake booster / master cylinder assembly at the firewall.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(650, 156, 'Fabricate and fit the mounting bracket for the electric master cylinder pump under the front fender, passenger side.', NULL, '✔ Confirm bracket location matches this build\'s standard — passenger side, under-fender.', NULL, NULL, 2, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(651, 156, 'Fabricate and fit the mounting bracket for the electric A/C pump under the front fender, driver side.', NULL, '✔ Confirm bracket location matches this build\'s standard — driver side, under-fender.', NULL, NULL, 3, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(652, 156, 'Confirm clearance to wheel, tyre and suspension travel for both fender-mounted pump brackets through full lock and full suspension travel.', NULL, '⚠ Check at full steering lock and full bump/droop — not just static.', NULL, NULL, 4, '2026-08-15 04:00:44', '2026-08-15 04:00:44');
INSERT INTO `vehicle_build_steps` (`id`, `vehicle_build_operation_id`, `label`, `type`, `keypoint_text`, `image_path`, `image_caption`, `order`, `created_at`, `updated_at`) VALUES
(653, 157, 'Run brake lines from the electric master cylinder pump (passenger fender) to the booster/master cylinder and forward to the front brake circuit fabricated in OP-501.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(654, 157, 'Run A/C lines from the electric A/C pump (driver fender) to the compressor/condenser circuit.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(655, 157, 'Route coolant hoses between radiator and engine, clear of exhaust and moving components.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(656, 157, 'Secure all lines with mounting clips at factory-style intervals; confirm no chafe points through full steering and suspension travel.', NULL, '⚠ Check at full steering lock and full suspension travel, both fender pump lines included.', NULL, NULL, 3, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(657, 158, 'Route and secure chassis wiring harness, keeping clear of heat sources and moving parts.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(658, 158, 'Connect lighting, fuel sender and chassis grounds; verify continuity at each circuit.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(659, 158, 'Confirm no shorts to chassis before battery connection.', NULL, '⚠ Do not connect battery until this check passes.', NULL, NULL, 2, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(660, 159, 'Connect engine harness to ECU and sensors; verify pinout against wiring diagram.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(661, 159, 'Wire gauge cluster, switch panel and accessory circuits; label all fuses/relays.', NULL, '✔ Every fuse/relay labelled and matched to the wiring diagram.', NULL, NULL, 1, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(662, 159, 'Power up and confirm ECU communication, gauge function and no fault codes.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(663, 160, 'Fit and align all body panels; confirm gaps and shut lines within spec.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(664, 160, 'Complete bodywork, filler and surface prep; seal and prime.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(665, 160, 'Apply base coat and clear coat in a controlled, ventilated booth; cure per paint manufacturer spec.', NULL, '⚠ Full respiratory protection required for 2K clear coat application.', NULL, NULL, 2, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(666, 160, 'Colour-sand and buff finished paint.', NULL, NULL, NULL, NULL, 3, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(667, 161, 'Install sound deadening, carpet, seats, seatbelts and console.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(668, 161, 'Install dash, gauges and interior trim.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(669, 161, 'Install glass, exterior trim and weatherstrip; confirm seals against water/wind intrusion.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:44', '2026-08-15 04:00:44'),
(670, 162, 'Fill all fluids — oil, coolant, transmission, differential, brake, power steering — to spec.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:45', '2026-08-15 04:00:45'),
(671, 162, 'Perform initial start-up with fire extinguisher on hand; check for leaks, unusual noise and correct idle.', NULL, '⚠ First start — extinguisher on hand, bay clear of flammables.', NULL, NULL, 1, '2026-08-15 04:00:45', '2026-08-15 04:00:45'),
(672, 162, 'Function-check all electrical systems: lighting, HVAC, wipers, gauges, infotainment.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:45', '2026-08-15 04:00:45'),
(673, 163, 'Set final wheel alignment (caster, camber, toe) per Front IFS spec (OP-100) and rear suspension spec.', NULL, NULL, NULL, NULL, 0, '2026-08-15 04:00:45', '2026-08-15 04:00:45'),
(674, 163, 'Complete low-speed shakedown, then extended road test; re-check alignment and torque all suspension/steering fasteners after settling.', NULL, NULL, NULL, NULL, 1, '2026-08-15 04:00:45', '2026-08-15 04:00:45'),
(675, 163, 'Complete ADR/RVSA compliance inspection checklist and compile compliance documentation for submission.', NULL, NULL, NULL, NULL, 2, '2026-08-15 04:00:45', '2026-08-15 04:00:45'),
